/*
  Данные схемы продвижения. Страница site/index.html читает window.SCHEMA.
  Как править:
  - risk: "g" без риска, "y" низкий риск, "r" высокий риск;
  - fines: ключи из раздела fines, суммы задаются в колонках self, ip, ooo; формы из forms берут сумму из своей колонки col или из своей строки (например none, ipnpd);
  - verify: true — сумма или норма ещё не сверена с официальным источником, на странице показывается пометка «сверить»;
  - после правки нормы запись в CHANGELOG.md и источник, как для навыков.
  - недостающие старты целей (Instagram, YouTube, Rutube и Дзен, TikTok, блогеры, Директ) собираются из шаблонов TPL
    по описанию цели в CTX; свой старт в start[цель] с тем же id заменяет шаблон;
  - заголовок второго шага у площадок собирается из поля obj цели: «Как продать {obj} через {площадка}».
*/
/* Связки для цели «Продать рекламу в своём канале»: одинаковые правила для каждой площадки,
   отличается только строка о самой площадке (note) и способ работы через платформу (exchange). */
