/* Шаблоны стартов, которых нет у цели: YouTube, Rutube и Дзен, TikTok, блогеры, Instagram, Директ.
   c — описание цели из CTX: p — префикс id, abt — «о чём» («о курсе»), acc — что продаём («курс»),
   home — куда ведут экспертные материалы, pay — где оплата, vkp — своё место в VK или home. */
const CTX = {
  book: { abt: "о памятке", acc: "памятку", home: ["site"], pay: ["site"], own: true },
  presale: { abt: "о предпродаже курса", acc: "предзапись на курс", home: ["plsite"], pay: ["plsite", "prepay"], dirNo: "Дата старта, которую вы не уверены, что выдержите" },
  course: { abt: "о курсе", acc: "курс", home: ["csite"], pay: ["csite", "gc"] },
  marathon: { abt: "о марафоне", acc: "марафон", home: ["marpage"], pay: ["marpage"] },
  club: { abt: "о клубе", acc: "доступ в клуб", home: ["clubsite", "clubvk"], pay: ["clubsite", "clubvk", "boosty"], vkp: ["clubvk"], tgp: ["tg", "clubtg"], dirNo: "Умолчать, что оплата списывается каждый месяц" },
  doula: { abt: "о сопровождении", acc: "сопровождение", home: ["dsite", "dvk"], pay: ["dsite", "dchat"], vkp: ["dvk"] },
  consult: { abt: "о консультациях", acc: "консультации", home: ["conslay", "conscall"], pay: ["conscall"] },
  event: { abt: "о мероприятии", acc: "билеты", home: ["evpage"], pay: ["evpage"] }
};
