  for (const id of ['logo','meta_pay']) if (D.fines[id]) {
    D.fines[id].verify = true;
    D.fines[id].note = 'Для конкретного случая нужен первичный судебный акт и проверка состава. Любая ссылка или любая платная функция автоматически нарушением не объявляется. ' + D.fines[id].note;
  }
  D.fines.mailing.note = 'Предварительное согласие доказывает рекламораспространитель; по требованию получателя рассылку прекращают немедленно. Рекомендации к сроку согласия отдельно даны в позиции ФАС, их не заменяют придуманным единым сроком.';
  D.fines.promo.note = 'Статья 9 применяется к мероприятиям, участие в которых обусловлено приобретением товара. Бесплатный розыгрыш и правила сервиса оцениваются отдельно.';
  const explain = (id, text, parts, basis) => { const x = D.explain.find(x => x.id === id); if (x) { x.text = text; x.parts = parts; x.basis = basis; delete x.yes; delete x.no; } };
