  explain('banned', ['Рекламную допустимость проверяют по ресурсу и конкретному размещению. Технически доступная публикация может быть запрещённой рекламой.', 'В Instagram реклама запрещена. Переходный период ФАС по Telegram и YouTube до конца 2026 года не является разрешением законом. Новый период на 2027 год не подтверждён.'], [{ title: 'Что требует подтверждения', items: ['Текущий статус ограничений TikTok.', 'Составы ответственности по символике, конкретным ссылкам и платежам: сообщения СМИ не заменяют первичный судебный акт.', 'Реклама средств доступа к ограниченным ресурсам и запрещённая информация о способах доступа — разные основания оценки.'] }], 'ч. 10.7 и 10.8 ст. 5 закона № 38-ФЗ; информация ФАС о переходном периоде. Сверка 23.11.2026');
