    c.here = { can: ['Подготовить копию ролика для выбранной площадки', 'Проверить права на ролик, музыку и изображения для повторного размещения', 'Отдельно оценить содержание и рекламный характер копии'], cannot: ['Считать публикацию копии подтверждённым переносом аудитории', 'Считать этот маршрут завершённой продажей материала'] };
